   213  template <typename KernSubTableHeader>
   214  struct KerxSubTableFormat1
   215  {
   216    typedef typename KernSubTableHeader::Types Types;
   217    typedef typename Types::HBUINT HBUINT;
   218
   219    typedef Format1Entry<Types::extended> Format1EntryT;
   220    typedef typename Format1EntryT::EntryData EntryData;
   221
   222    struct driver_context_t
   223    {
   224      static const bool in_place = true;
   225      enum
   226      {
   227        DontAdvance       = Format1EntryT::DontAdvance,
   228      };
   229
   230      inline driver_context_t (const KerxSubTableFormat1 *table_,
   231                               hb_aat_apply_context_t *c_) :
   232          c (c_),
   233          table (table_),
   234          /* Apparently the offset kernAction is from the beginning of the state-machine,
   235           * similar to offsets in morx table, NOT from beginning of this table, like
   236           * other subtables in kerx.  Discovered via testing. */
   237          kernAction (&table->machine + table->kernAction),
   238          depth (0),
   239          crossStream (table->header.coverage & table->header.CrossStream) {}
   240
   241      inline bool is_actionable (StateTableDriver<Types, EntryData> *driver HB_UNUSED,
   242                                 const Entry<EntryData> *entry)
   243      {
   244        return Format1EntryT::performAction (entry);
   245      }
   246      inline bool transition (StateTableDriver<Types, EntryData> *driver,
   247                              const Entry<EntryData> *entry)
   248      {
   249        hb_buffer_t *buffer = driver->buffer;
   250        unsigned int flags = entry->flags;
   251
   252        if (flags & Format1EntryT::Reset)
   253          depth = 0;
   254
   255        if (flags & Format1EntryT::Push)
   256        {
   257          if (likely (depth < ARRAY_LENGTH (stack)))
   258            stack[depth++] = buffer->idx;
   259          else
   260            depth = 0; /* Probably not what CoreText does, but better? */
   261        }
   262
   263        if (Format1EntryT::performAction (entry))
   264        {
   265          unsigned int tuple_count = MAX (1u, table->header.tuple_count ());
   266
   267          unsigned int kern_idx = Format1EntryT::kernActionIndex (entry);
   268          kern_idx = Types::offsetToIndex (kern_idx, &table->machine, kernAction.arrayZ);
   269          const FWORD *actions = &kernAction[kern_idx];
   270          if (!c->sanitizer.check_array (actions, depth * tuple_count))
   271          {
   272            depth = 0;
   273            return false;
   274          }
   275
   276          hb_mask_t kern_mask = c->plan->kern_mask;
   277
   278          /* From Apple 'kern' spec:
   279           * "Each pops one glyph from the kerning stack and applies the kerning value to it.
   280           * The end of the list is marked by an odd value... */
   281          bool last = false;
   282          while (!last && depth--)
   283          {
   284            unsigned int idx = stack[depth];
   285            int v = *actions;
   286            actions += tuple_count;
   287            if (idx >= buffer->len) continue;
   288
   289            /* "The end of the list is marked by an odd value..." */
   290            last = v & 1;
   291            v &= ~1;
   292
   293            hb_glyph_position_t &o = buffer->pos[idx];
   294
   295            /* Testing shows that CoreText only applies kern (cross-stream or not)
   296             * if none has been applied by previous subtables.  That is, it does
   297             * NOT seem to accumulate as otherwise implied by specs. */
   298
   299            /* The following flag is undocumented in the spec, but described
   300             * in the 'kern' table example. */
   301            if (v == -0x8000)
   302            {
   303              o.attach_type() = ATTACH_TYPE_NONE;
   304              o.attach_chain() = 0;
   305              o.x_offset = o.y_offset = 0;
   306            }
   307            else if (HB_DIRECTION_IS_HORIZONTAL (buffer->props.direction))
   308            {
   309              if (crossStream)
   310              {
   311                if (buffer->pos[idx].attach_type() && !buffer->pos[idx].y_offset)
   312                {
   313                  o.y_offset = c->font->em_scale_y (v);
   314                  buffer->scratch_flags |= HB_BUFFER_SCRATCH_FLAG_HAS_GPOS_ATTACHMENT;
   315                }
   316              }
   317              else if (buffer->info[idx].mask & kern_mask)
   318              {
   319                if (!buffer->pos[idx].x_offset)
   320                {
   321                  buffer->pos[idx].x_advance += c->font->em_scale_x (v);
   322                  buffer->pos[idx].x_offset += c->font->em_scale_x (v);
   323                }
   324              }
   325            }
   326            else
   327            {
   328              if (crossStream)
   329              {
   330                /* CoreText doesn't do crossStream kerning in vertical.  We do. */
   331                if (buffer->pos[idx].attach_type() && !buffer->pos[idx].x_offset)
   332                {
   333                  o.x_offset = c->font->em_scale_x (v);
   334                  buffer->scratch_flags |= HB_BUFFER_SCRATCH_FLAG_HAS_GPOS_ATTACHMENT;
   335                }
   336              }
   337              else if (buffer->info[idx].mask & kern_mask)
   338              {
   339                if (!buffer->pos[idx].y_offset)
   340                {
   341                  buffer->pos[idx].y_advance += c->font->em_scale_y (v);
   342                  buffer->pos[idx].y_offset += c->font->em_scale_y (v);
   343                }
   344              }
   345            }
   346          }
   347        }
   348
   349        return true;
   350      }
   351
   352      private:
   353      hb_aat_apply_context_t *c;
   354      const KerxSubTableFormat1 *table;
   355      const UnsizedArrayOf<FWORD> &kernAction;
   356      unsigned int stack[8];
   357      unsigned int depth;
   358      bool crossStream;
   359    };
